package com.playvibe.live;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.Gravity;import android.view.View;import android.widget.*;
public class MainActivity extends Activity{
 LinearLayout root,body;TextView balance;int coins=120,bg=0xff101426,accent=0xffff4f91;String creator="Guest Creator";
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 GradientDrawable box(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
 GradientDrawable grad(int a,int b){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{a,b});d.setCornerRadius(dp(18));return d;}
 TextView txt(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(-1);v.setPadding(dp(9),dp(8),dp(9),dp(8));return v;}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 void gap(){View v=new View(this);body.addView(v,new LinearLayout.LayoutParams(1,dp(10)));}
 void btn(LinearLayout b,String s,Runnable r){TextView v=txt(s,15);v.setGravity(17);v.setTypeface(null,1);v.setBackground(grad(accent,0xff7950df));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.setMargins(0,dp(5),0,dp(8));b.addView(v,p);v.setOnClickListener(w->r.run());}
 void card(String icon,String name,String sub,Runnable r){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(12),dp(8),dp(12),dp(8));c.setBackground(grad(0xff292d4a,0xff20243b));c.addView(txt(icon+"  "+name,17));TextView s=txt(sub,12);s.setTextColor(0xffc7c9dc);c.addView(s);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));body.addView(c,p);c.setOnClickListener(w->r.run());}
 void heading(String s,String sub){body.addView(txt(s,24));TextView t=txt(sub,13);t.setTextColor(0xffc7c9dc);body.addView(t);}
 void info(String s){new AlertDialog.Builder(this).setTitle("Feature connection needed").setMessage(s).setPositiveButton("OK",null).show();}
 void page(String p){body.removeAllViews();
 switch(p){
 case "Home":heading("PLAYVIBE LIVE","Meet • Stream • Chat • Play");LinearLayout hero=new LinearLayout(this);hero.setOrientation(1);hero.setPadding(dp(14),dp(14),dp(14),dp(14));hero.setBackground(grad(0xffe83f87,0xff7048d8));hero.addView(txt("YOUR VIBE. YOUR LIVE.",21));hero.addView(txt("Connect with friends and creators",13));btn(hero,"Explore Live Rooms",()->page("Live"));body.addView(hero);gap();card("🔴","Live Rooms","Discover creator streams",()->page("Live"));card("💬","Messages","Open your chat inbox",()->page("Messages"));card("🎁","Gifts & Coins","Wallet: "+coins+" demo coins",()->page("Gifts"));card("🎮","Games","Play together",()->page("Games"));card("👤","My Profile","Customize your profile and app theme",()->page("Profile"));break;
 case "Live":heading("Live Rooms","Sample creator rooms");card("🎤","Music Lounge","Live stream preview • not connected",()->page("Room"));card("🎮","Gaming Zone","Creator room preview",()->page("Room"));btn(body,"＋ Start My Live",()->info("Real live video requires a streaming server, camera/audio permissions and creator accounts."));break;
 case "Room":heading("Creator Live Room","Room preview");LinearLayout stage=new LinearLayout(this);stage.setGravity(17);stage.setOrientation(1);stage.setPadding(dp(10),dp(45),dp(10),dp(45));stage.setBackground(grad(0xff40245f,0xff171c34));stage.addView(txt("▶",40));stage.addView(txt("LIVE VIDEO PREVIEW",17));stage.addView(txt("Video stream is not connected",12));body.addView(stage);gap();btn(body,"📹 Video Call",()->info("Video calling needs a real-time video service and user accounts."));btn(body,"💬 Room Chat",()->page("Messages"));btn(body,"🎁 Send Gift",()->page("Gifts"));break;
 case "Messages":heading("Messages","Local preview chat on this phone");TextView history=txt("PLAYVIBE BOT • Welcome!\n\nThis chat is local only. Messages are not delivered to other users yet.",14);history.setBackground(box(0xff292d49,15));body.addView(history);EditText input=new EditText(this);input.setSingleLine(true);input.setHint("Type a message");input.setTextColor(-1);input.setHintTextColor(0xffb8bdd0);input.setBackground(box(0xff303650,12));body.addView(input);btn(body,"Send preview message",()->{String m=input.getText().toString().trim();if(m.isEmpty())toast("Write a message first");else{history.append("\n\nYOU • "+m);input.setText("");}});break;
 case "Gifts":heading("Coins & Gifts","Demo coins have no cash value");TextView wallet=txt("🪙 "+coins+" COINS",22);wallet.setGravity(17);wallet.setBackground(grad(0xff7048d8,0xffd94691));body.addView(wallet);gap();card("🌹","Rose • 10 coins","Send demo gift",()->gift(10));card("💎","Diamond • 50 coins","Send demo gift",()->gift(50));card("👑","Crown • 100 coins","Send demo gift",()->gift(100));btn(body,"＋ Add 100 demo coins",()->{coins+=100;page("Gifts");refresh();});break;
 case "Games":heading("Play Together","Game room previews");card("🎲","Ludo Room","Local / online game integration pending",()->info("Online multiplayer requires a game server."));card("⭕","Tic Tac Toe","Coming soon",()->toast("Coming soon"));break;
 case "Profile":heading("My Profile","Make your creator profile yours");TextView av=txt("PV",30);av.setGravity(17);av.setBackground(grad(accent,0xff7048d8));LinearLayout.LayoutParams a=new LinearLayout.LayoutParams(dp(78),dp(78));a.gravity=1;body.addView(av,a);TextView nm=txt(creator,20);nm.setGravity(17);body.addView(nm);btn(body,"✏️ Edit display name",()->{EditText e=new EditText(this);e.setText(creator);new AlertDialog.Builder(this).setTitle("Creator name").setView(e).setPositiveButton("Save",(d,w)->{if(e.length()>0){creator=e.getText().toString();nm.setText(creator);}}).setNegativeButton("Cancel",null).show();});btn(body,"🎨 Change app background",()->theme());btn(body,"🪙 My Wallet",()->page("Gifts"));card("🔒","Account & Safety","Secure accounts and moderation need setup",()->info("Sign-in, blocking, reporting and moderation must be connected before public launch."));break;
 }}
 void refresh(){if(balance!=null)balance.setText("🪙 "+coins);}
 void gift(int n){if(coins<n){toast("Not enough demo coins");return;}coins-=n;refresh();toast("Demo gift sent");page("Gifts");}
 void theme(){String[] names={"Midnight Purple","Ocean Blue","Sunset Pink","Emerald"};int[] c={0xff101426,0xff09253e,0xff32152b,0xff092a25};new AlertDialog.Builder(this).setTitle("Choose background").setItems(names,(d,w)->{bg=c[w];root.setBackground(grad(bg,0xff30204a));page("Profile");toast(names[w]+" applied");}).show();}
 void nav(LinearLayout n,String s,String p){TextView v=txt(s,10);v.setGravity(17);n.addView(v,new LinearLayout.LayoutParams(0,dp(50),1));v.setOnClickListener(w->page(p));}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff101426);getWindow().setNavigationBarColor(0xff101426);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(14),dp(12),dp(14),dp(5));root.setBackground(grad(bg,0xff30204a));setContentView(root);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView brand=txt("◈ PLAYVIBE LIVE",20);brand.setTypeface(null,1);head.addView(brand,new LinearLayout.LayoutParams(0,-2,1));balance=txt("🪙 "+coins,14);balance.setBackground(box(0xff393052,20));head.addView(balance);root.addView(head);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setBackground(box(0xff20243b,18));nav(nav,"⌂ Home","Home");nav(nav,"● Live","Live");nav(nav,"✉ Chat","Messages");nav(nav,"🎁 Gifts","Gifts");nav(nav,"☺ Profile","Profile");root.addView(nav);page("Home");}
}